# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HOW TO MAKE AN OMELETTE (SEQUENCE LINKERS &amp; IMPERATIVES)</text>\n  <rect x="20" y="48" width="210" height="92" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. FIRST (İlk Olarak)</text>\n  <text x="125" y="96" text-anchor="middle" font-size="11.5" fill="#1e3a8a">Put some oil into a pan</text>\n  <text x="125" y="114" text-anchor="middle" font-size="11.5" fill="#1e3a8a">and heat it.</text>\n  <text x="125" y="132" text-anchor="middle" font-size="10" fill="#475569">(Tavaya yağ koy ve ısıt.)</text>\n  <rect x="245" y="48" width="210" height="92" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. SECOND (İkinci Olarak)</text>\n  <text x="350" y="96" text-anchor="middle" font-size="11.5" fill="#14532d">Crack and mix two eggs</text>\n  <text x="350" y="114" text-anchor="middle" font-size="11.5" fill="#14532d">in a bowl with a whisk.</text>\n  <text x="350" y="132" text-anchor="middle" font-size="10" fill="#475569">(Kasede iki yumurtayı çırp.)</text>\n  <rect x="470" y="48" width="210" height="92" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">3. NEXT / THEN (Sonra)</text>\n  <text x="575" y="96" text-anchor="middle" font-size="11.5" fill="#713f12">Add a pinch of salt and</text>\n  <text x="575" y="114" text-anchor="middle" font-size="11.5" fill="#713f12">some grated cheese.</text>\n  <text x="575" y="132" text-anchor="middle" font-size="10" fill="#475569">(Tuz ve rendelenmiş peynir ekle.)</text>\n  <rect x="20" y="152" width="325" height="90" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="182" y="176" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">4. AFTER THAT (Ardından)</text>\n  <text x="182" y="200" text-anchor="middle" font-size="11.5" fill="#831843">Pour the mixture into the hot frying pan.</text>\n  <text x="182" y="222" text-anchor="middle" font-size="10.5" fill="#475569">(Karışımı sıcak kızartma tavasına dök.)</text>\n  <rect x="360" y="152" width="320" height="90" rx="8" fill="#f3e8ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="176" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">5. FINALLY (Son Olarak)</text>\n  <text x="520" y="200" text-anchor="middle" font-size="11.5" fill="#581c87">Fry both sides for 3 minutes and serve hot.</text>\n  <text x="520" y="222" text-anchor="middle" font-size="10.5" fill="#475569">(İki tarafını 3 dakika pişir ve sıcak servis et.)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">READING A RECIPE: INGREDIENTS, QUANTITIES &amp; ACTIONS</text>\n  <rect x="25" y="48" width="315" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13.5" font-weight="bold" fill="#1d4ed8">Quantities &amp; Measurements (Miktarlar)</text>\n  <text x="40" y="98" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#1e3a8a">a tablespoon of</tspan> olive oil (1 yemek kaşığı yağ)</text>\n  <text x="40" y="120" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#1e3a8a">a teaspoon of</tspan> salt / sugar (1 çay kaşığı tuz)</text>\n  <text x="40" y="142" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#1e3a8a">a cup / glass of</tspan> flour / milk (1 bardak un/süt)</text>\n  <text x="40" y="164" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#1e3a8a">two cloves of</tspan> garlic (2 diş sarımsak)</text>\n  <text x="40" y="186" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#1e3a8a">a pinch of</tspan> black pepper (1 tutam karabiber)</text>\n  <text x="40" y="208" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#1e3a8a">a handful of</tspan> parsley (1 avuç maydanoz)</text>\n  <text x="40" y="228" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#1e3a8a">a packet of</tspan> pasta (1 paket makarna)</text>\n  <rect x="360" y="48" width="315" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13.5" font-weight="bold" fill="#15803d">Key Preparation Verbs (Hazırlık Fiilleri)</text>\n  <text x="375" y="98" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#14532d">peel</tspan> (soymak) / <tspan font-weight="bold" fill="#14532d">chop</tspan> (doğramak) / <tspan font-weight="bold" fill="#14532d">dice</tspan> (küp doğramak)</text>\n  <text x="375" y="122" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#14532d">slice</tspan> (dilimlemek) / <tspan font-weight="bold" fill="#14532d">grate</tspan> (rendelemek)</text>\n  <text x="375" y="146" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#14532d">mash</tspan> (ezmek/püre yapmak) / <tspan font-weight="bold" fill="#14532d">knead</tspan> (yoğurmak)</text>\n  <text x="375" y="170" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#14532d">whisk / beat</tspan> (çırpmak) / <tspan font-weight="bold" fill="#14532d">stir</tspan> (karıştırmak)</text>\n  <text x="375" y="194" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#14532d">pour</tspan> (dökmek) / <tspan font-weight="bold" fill="#14532d">drain / strain</tspan> (süzmek)</text>\n  <text x="375" y="218" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#14532d">sprinkle</tspan> (serpmek) / <tspan font-weight="bold" fill="#14532d">spread</tspan> (sürmek/yaymak)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MAKING SIMPLE INQUIRIES ABOUT COOKING PROCESSES</text>\n  <rect x="25" y="50" width="315" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="182" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Questions About Ingredients &amp; Tools</text>\n  <text x="40" y="102" font-size="11.5" font-weight="bold" fill="#854d0e">• What are the ingredients of lentil soup?</text>\n  <text x="48" y="120" font-size="11" fill="#334155">→ Red lentils, an onion, a carrot, oil and salt.</text>\n  <text x="40" y="146" font-size="11.5" font-weight="bold" fill="#854d0e">• Do I use two or three eggs for the cake?</text>\n  <text x="48" y="164" font-size="11" fill="#334155">→ Three eggs are enough.</text>\n  <text x="40" y="190" font-size="11.5" font-weight="bold" fill="#854d0e">• What can/should I use to drain the pasta?</text>\n  <text x="48" y="208" font-size="11" fill="#334155">→ You should use a strainer (colander).</text>\n  <rect x="360" y="50" width="315" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="517" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Questions About Steps &amp; Time</text>\n  <text x="375" y="102" font-size="11.5" font-weight="bold" fill="#9d174d">• What is the first / next step after boiling?</text>\n  <text x="383" y="120" font-size="11" fill="#334155">→ Next, drain the boiled potatoes and mash them.</text>\n  <text x="375" y="146" font-size="11.5" font-weight="bold" fill="#9d174d">• How long does it take to bake the chicken?</text>\n  <text x="383" y="164" font-size="11" fill="#334155">→ Bake it in a preheated oven for 40 minutes.</text>\n  <text x="375" y="190" font-size="11.5" font-weight="bold" fill="#9d174d">• How do you usually serve this dessert?</text>\n  <text x="383" y="208" font-size="11" fill="#334155">→ We serve it cold with some ice cream on top.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
